package images_test

import (
	"fmt"
	"testing"

	"github.com/gohugoio/hugo/markup/goldmark/images"
	"github.com/gohugoio/hugo/markup/goldmark/internal/extensions/attributes"
	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/text"
	"github.com/yuin/goldmark/util"
	"github.com/yuin/goldmark/ast"
)

type dumpT struct{ name string }
func (d *dumpT) Transform(doc *ast.Document, reader text.Reader, pctx parser.Context) {
	fmt.Println("=== after", d.name, "===")
	doc.Dump(reader.Source(), 0)
}

func TestDebugAST(t *testing.T) {
	for _, text := range []string{
		"![alt](a.jpg)\n{.foo #bar}\n",
		"para\n{.foo #bar}\n",
		"![alt](a.jpg)\n\n{.foo #bar}\n",
		"# Heading\n{.foo #bar}\n",
	} {
		fmt.Println("##### INPUT", text)
		md := goldmark.New(
			goldmark.WithExtensions(images.New(false), attributes.New()),
			goldmark.WithParserOptions(parser.WithASTTransformers(
				util.Prioritized(&dumpT{"50"}, 50),
				util.Prioritized(&dumpT{"200"}, 200),
				util.Prioritized(&dumpT{"400"}, 400),
			)),
		)
		src := []byte(text)
		doc := md.Parser().Parse(text.NewReader(src))
		doc.Dump(src, 0)
	}
}
EOF
